<?php $checks=[['Trial balance',$finance['debits'],$finance['credits'],'Debits','Credits']]; if($access['receivables'])$checks[]=['Accounts receivable',$finance['ar_ledger'],$finance['receivables'],'Ledger','Invoices'];if($access['payables'])$checks[]=['Accounts payable',$finance['ap_ledger'],$finance['payables'],'Ledger','Bills']; ?>
<article class="dashboard-enter bg-white rounded-xl border border-slate-200 shadow-sm min-w-0 overflow-hidden">
    <h2 class="text-sm font-bold text-slate-900 p-3">Reconciliation</h2>
    <div class="overflow-x-auto"><table class="w-full text-left text-xs"><thead class="bg-brand-50 text-[10px] text-slate-500"><tr><th class="px-3 py-2">Check</th><th class="px-3 py-2">Balances (USD)</th><th class="px-3 py-2 text-right">Difference</th><th class="px-3 py-2">Status</th></tr></thead><tbody class="divide-y divide-slate-100">
        <?php foreach ($checks as [$label,$ledger,$documents,$left,$right]): $difference=round($ledger-$documents,2);$matched=abs($difference)<0.005;$available=$finance['has_entries']; ?><tr><td class="px-3 py-2 font-semibold"><?= esc($label) ?></td><td class="px-3 py-2 whitespace-nowrap text-[10px]"><?= esc($left) ?>: <?= number_format($ledger,2) ?><br><?= esc($right) ?>: <?= number_format($documents,2) ?></td><td class="px-3 py-2 text-right tabular-nums <?= $matched?'':'text-rose-600' ?>"><?= number_format($difference,2) ?></td><td class="px-3 py-2"><span class="rounded-md px-1.5 py-0.5 text-[10px] font-semibold <?= !$available?'bg-slate-100 text-slate-500':($matched?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-700') ?>"><?= !$available?'No entries':($matched?'Matched':'Review') ?></span></td></tr><?php endforeach; ?>
    </tbody></table></div>
    <p class="text-[10px] text-slate-500 m-3 p-2 rounded-lg bg-slate-50"><?= $finance['period'] ? esc($finance['period']['name'].' · '.ucfirst($finance['period']['status'])) : 'No financial period configured for this date.' ?></p>
</article>
